const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artiklar</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Den tyske artikkelen samsvarar ikkje alltid med kjønnet ordet har på norsk. Difor er det best å lære substantiva saman med artikkelen.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Døme på artiklar</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — bord</div>\n      <div class=\"kurss-example\">die Tür — dør</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">das Mädchen — jente</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Ofte DER</h4>\n    <p class=\"artikuli-explain\">DER blir ofte brukt om mannlege personar, dagar, månader, årstider og nokre ord med bestemte endingar.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglar</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → ofte DER, til dømes: der Computer, der Lehrer <span class=\"artikuli-note\">men ikkje alltid</span></div>\n      <div class=\"kurss-example\">-ling → ofte DER, til dømes: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → ofte DER, til dømes: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">mannlege personar → der Mann, der Vater</div>\n      <div class=\"kurss-example\">yrke → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">bilmerke → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dagar → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">månader → der August, der Dezember</div>\n      <div class=\"kurss-example\">årstider → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Døme</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — mann</div>\n      <div class=\"kurss-example\">der Vater — far</div>\n      <div class=\"kurss-example\">der Montag — måndag</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — sommar</div>\n      <div class=\"kurss-example\">der Lehrer — lærar</div>\n      <div class=\"kurss-example\">der Computer — datamaskin</div>\n      <div class=\"kurss-example\">der Schmetterling — sommarfugl</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Ofte DIE</h4>\n    <p class=\"artikuli-explain\">DIE blir ofte brukt om kvinnelege personar, fleirtal og ord med endingane -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglar</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">kvinnelege personar → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motorsykkelmerke → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">fleirtal → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">fleirtal nesten alltid → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Døme</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — kvinne</div>\n      <div class=\"kurss-example\">die Mutter — mor</div>\n      <div class=\"kurss-example\">die Wohnung — leilegheit</div>\n      <div class=\"kurss-example\">die Rechnung — rekning</div>\n      <div class=\"kurss-example\">die Freiheit — fridom</div>\n      <div class=\"kurss-example\">die Möglichkeit — moglegheit</div>\n      <div class=\"kurss-example\">die Mannschaft — lag</div>\n      <div class=\"kurss-example\">die Nation — nasjon</div>\n      <div class=\"kurss-example\">die Universität — universitet</div>\n      <div class=\"kurss-example\">die Polizei — politi</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Ofte DAS</h4>\n    <p class=\"artikuli-explain\">DAS blir ofte brukt om diminutivar på -chen / -lein, mange ord på -ment / -um og verb brukte som substantiv.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglar</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metall → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">kjemiske grunnstoff → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotell → das Hotel</div>\n      <div class=\"kurss-example\">fargar som substantiv → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verb som substantiv → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verb brukte som substantiv → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Døme</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — barn</div>\n      <div class=\"kurss-example\">das Mädchen — jente</div>\n      <div class=\"kurss-example\">das Häuschen — lite hus</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — sentrum</div>\n      <div class=\"kurss-example\">das Museum — museum</div>\n      <div class=\"kurss-example\">das Essen — eting / mat</div>\n      <div class=\"kurss-example\">das Lernen — læring</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Viktige unntak / må lærast med artikkelen</h4>\n    <p class=\"artikuli-explain\">For nokre ord kan ein ikkje sikkert avgjere artikkelen ut frå endinga eller kjønnet ordet har på norsk. Desse orda er det best å lære saman med artikkelen.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — dør</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">die Sonne — sol</div>\n      <div class=\"kurss-example\">der Mond — måne</div>\n      <div class=\"kurss-example\">das Mädchen — jente</div>\n      <div class=\"kurss-example\">das Auto — bil</div>\n      <div class=\"kurss-example\">der Käse — ost</div>\n      <div class=\"kurss-example\">die Gabel — gaffel</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Endingar og ordgrupper hjelper deg å gjette artikkelen, men dei er ingen 100% sikker regel. Er du usikker, lær ordet saman med artikkelen.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronomen</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ og Dativ — formene til pronomena.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kven/kva?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — eg</div><div class=\"kurss-example\">du — du</div><div class=\"kurss-example\">er — han</div><div class=\"kurss-example\">sie — ho</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">wir — vi</div><div class=\"kurss-example\">ihr — de</div><div class=\"kurss-example\">sie — dei</div><div class=\"kurss-example\">Sie — De (høfleg)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — kven/kva?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — meg</div><div class=\"kurss-example\">dich — deg</div><div class=\"kurss-example\">ihn — han (m.)</div><div class=\"kurss-example\">sie — henne (f.)</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">uns — oss</div><div class=\"kurss-example\">euch — dykk</div><div class=\"kurss-example\">sie — dei</div><div class=\"kurss-example\">Sie — Dykk (høfleg)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — til kven?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — (til) meg</div><div class=\"kurss-example\">dir — (til) deg</div><div class=\"kurss-example\">ihm — (til) han / det</div><div class=\"kurss-example\">ihr — (til) henne</div><div class=\"kurss-example\">uns — (til) oss</div><div class=\"kurss-example\">euch — (til) dykk</div><div class=\"kurss-example\">ihnen — (til) dei</div><div class=\"kurss-example\">Ihnen — (til) Dykk (høfleg)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Korleis vel ein rett form?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — subjekt (kven gjer noko?)</li><li><span class=\"case-red\">Akkusativ</span> — direkte objekt (kven/kva?)</li><li><span class=\"case-green\">Dativ</span> — indirekte objekt (til kven?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Døme</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Eg ser deg.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Eg ser han.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Vi likar dykk.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Eg hjelper deg.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Eg gjev han ei bok.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Vi takkar dykk.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ er alltid subjektet i setninga, medan Akkusativ og Dativ er objekt. Sjå på verbet og spør: <span class=\"case-red\">kven/kva?</span> eller <span class=\"case-green\">til kven?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vokalar — lange og korte</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>På tysk kan vokalane vere lange eller korte. Det påverkar korleis ordet blir uttalt.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lang vokal</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — varm</div><div class=\"kurss-example\">gut (gūt) — god</div><div class=\"kurss-example\">Tat (tāt) — gjerning / handling</div><div class=\"kurss-example\">Flur (flūr) — gang / korridor</div><div class=\"kurss-example\">Weg (vēk) — veg</div><div class=\"kurss-example\">Hut (hūt) — hatt</div><div class=\"kurss-example\">Hof (hå̄f) — gard / tun</div><div class=\"kurss-example\">Schlaf (sjlāf) — søvn</div></div>\n              <p class=\"artikuli-explain\">Når det kjem éin konsonant etter vokalen, blir vokalen ofte uttalt lang.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kort vokal</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilts) — sopp</div><div class=\"kurss-example\">Wort (vårt) — ord</div><div class=\"kurss-example\">Mund (munt) — munn</div><div class=\"kurss-example\">bald (balt) — snart</div><div class=\"kurss-example\">scharf (sjarf) — skarp</div><div class=\"kurss-example\">Feld (felt) — åker / mark</div><div class=\"kurss-example\">voll (fåll) — full</div></div>\n              <p class=\"artikuli-explain\">Når det kjem to eller fleire konsonantar etter vokalen, blir vokalen ofte uttalt kort.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Endingane en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — syngje</div><div class=\"kurss-example\">tragen (trāgen) — bere</div><div class=\"kurss-example\">Garten (garten) — hage</div><div class=\"kurss-example\">Vogel (få̄gel) — fugl</div><div class=\"kurss-example\">Segel (zēgel) — segl</div><div class=\"kurss-example\">Braten (brāten) — steik</div><div class=\"kurss-example\">Bogen (bå̄gen) — boge</div><div class=\"kurss-example\">Spiegel (sjpīgel) — spegel</div><div class=\"kurss-example\">Finger (finger) — finger</div><div class=\"kurss-example\">Halter (halter) — haldar</div><div class=\"kurss-example\">Arbeiter (arbaiter) — arbeidar</div><div class=\"kurss-example\">Häuser (håyzer) — hus (fleirtal)</div><div class=\"kurss-example\">wieder (vīder) — igjen</div><div class=\"kurss-example\">breiter (braiter) — breiare</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Bokstaven h som lengdeteikn</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (rāmen) — ramme</div><div class=\"kurss-example\">Ohr (å̄r) — øyre</div><div class=\"kurss-example\">Kohle (kå̄le) — kol</div><div class=\"kurss-example\">Zahl (tsāl) — tal</div><div class=\"kurss-example\">ihn (īn) — han (akkusativ)</div><div class=\"kurss-example\">ihm (īm) — han / til han (dativ)</div><div class=\"kurss-example\">Huhn (hūn) — høne</div><div class=\"kurss-example\">nahm (nām) — tok</div><div class=\"kurss-example\">nehmen (nēmen) — ta</div><div class=\"kurss-example\">Schuh (sjū) — sko</div></div>\n              <p class=\"artikuli-explain\">I nokre ord gjer h den føregåande vokalen lang. I slike tilfelle blir h vanlegvis ikkje uttalt.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Endingar på e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lampe</div><div class=\"kurss-example\">Hase (hāze) — hare</div><div class=\"kurss-example\">Knabe (knābe) — gut</div><div class=\"kurss-example\">Rabe (rābe) — ramn</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lang i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dī) — artikkelen «die»</div><div class=\"kurss-example\">diese (dīze) — denne / desse</div><div class=\"kurss-example\">wieder (vīder) — igjen</div><div class=\"kurss-example\">Fliege (flīge) — flue</div><div class=\"kurss-example\">Ziege (tsīge) — geit</div><div class=\"kurss-example\">Stiel (sjtīl) — skaft / stilk</div><div class=\"kurss-example\">Dieb (dīp) — tjuv</div><div class=\"kurss-example\">hier (hīr) — her</div></div>\n              <p class=\"artikuli-explain\">Lang i blir på tysk ofte skriven som ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dobbelvokalar</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zāl) — sal</div><div class=\"kurss-example\">Saat (zāt) — såkorn / såing</div><div class=\"kurss-example\">Staat (sjtāt) — stat</div><div class=\"kurss-example\">Beere (bēre) — bær</div><div class=\"kurss-example\">See (zē) — innsjø / hav</div><div class=\"kurss-example\">Beet (bēt) — bed (blomsterbed)</div><div class=\"kurss-example\">Boot (bå̄t) — båt</div><div class=\"kurss-example\">Moor (må̄r) — myr</div><div class=\"kurss-example\">Moos (må̄s) — mose</div></div>\n              <p class=\"artikuli-explain\">Dobbelvokalar blir vanlegvis uttalte lange.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — vegg</div><div class=\"kurss-example\">Wände (vende) — veggar</div><div class=\"kurss-example\">Vater (fāter) — far</div><div class=\"kurss-example\">Väter (fǣter) — fedrar</div><div class=\"kurss-example\">Schrank (sjrank) — skap</div><div class=\"kurss-example\">Schränke (sjrenke) — skap (fleirtal)</div><div class=\"kurss-example\">Bank (bank) — benk / bank</div><div class=\"kurss-example\">Bänke (benke) — benkar</div><div class=\"kurss-example\">Tal (tāl) — dal</div><div class=\"kurss-example\">Täler (tǣler) — dalar</div></div>\n              <p class=\"artikuli-explain\">ä er omlyden av a.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rå̄ze) — rose</div><div class=\"kurss-example\">Röschen (rø̄s-kjen) — lita rose</div><div class=\"kurss-example\">Ofen (å̄fen) — omn</div><div class=\"kurss-example\">Öfen (ø̄fen) — omnar</div><div class=\"kurss-example\">Rock (råkk) — skjørt</div><div class=\"kurss-example\">Röcke (røkke) — skjørt (fleirtal)</div></div>\n              <p class=\"artikuli-explain\">ö er omlyden av o.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kurts) — kort</div><div class=\"kurss-example\">kürzer (kyrtser) — kortare</div><div class=\"kurss-example\">Kunst (kunst) — kunst</div><div class=\"kurss-example\">Künste (kynste) — kunstar</div><div class=\"kurss-example\">Mutter (mutter) — mor</div><div class=\"kurss-example\">Mütter (mytter) — mødrer</div></div>\n              <p class=\"artikuli-explain\">ü er omlyden av u.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongar: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — tre</div><div class=\"kurss-example\">Bäume (båyme) — tre (fleirtal)</div><div class=\"kurss-example\">Haus (haus) — hus</div><div class=\"kurss-example\">Häuser (håyzer) — hus (fleirtal)</div><div class=\"kurss-example\">Strauch (sjtraukh) — busk</div><div class=\"kurss-example\">Sträucher (sjtråykjer) — buskar</div><div class=\"kurss-example\">Maus (maus) — mus</div><div class=\"kurss-example\">Mäuse (måyze) — mus (fleirtal)</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongar: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (håyte) — i dag</div><div class=\"kurss-example\">Leute (låyte) — folk</div><div class=\"kurss-example\">neu (nåy) — ny</div><div class=\"kurss-example\">neun (nåyn) — ni</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongar: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (main) — min</div><div class=\"kurss-example\">dein (dain) — din</div><div class=\"kurss-example\">sein (zain) — hans / sin / vere</div><div class=\"kurss-example\">frei (frai) — fri</div><div class=\"kurss-example\">arbeiten (arbaiten) — arbeide</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Uttalemerknader til 2. økt</h4>\n              <ul class=\"kurss-summary-list\"><li>i orda ich, nicht, rechnen, zeichnen blir «ch» uttalt mjukt, omtrent som norsk «kj» i «kjøpe»</li><li>i orda arbeiten og zeichnen blir «ei» uttalt som «ai»</li><li>«sp» i byrjinga av eit ord blir uttalt som «sjp»</li><li>i verbet tun skal «u» uttalast lang</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Samandrag</h4>\n              <ul class=\"kurss-summary-list\"><li>éin konsonant etter vokalen → ofte lang vokal</li><li>to eller fleire konsonantar → ofte kort vokal</li><li>h kan gjere vokalen lang</li><li>ie tyder ofte lang i</li><li>dobbelvokalar er vanlegvis lange</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Konsonantar og bokstavkombinasjonar</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>På tysk blir somme konsonantar og bokstavkombinasjonar uttalte annleis enn dei blir skrivne. I denne økta finn du dei viktigaste døma for nybyrjarar.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Konsonantar</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (das rāt) — hjul</div><div class=\"kurss-example\">die Räder (dī rǣder) — hjul (fleirtal)</div><div class=\"kurss-example\">Bad (bāt) — bad</div><div class=\"kurss-example\">Bäder (bǣder) — bad (fleirtal)</div></div>\n              <p class=\"artikuli-explain\">I slutten av eit ord blir konsonantane ofte ikkje uttalte slik dei blir skrivne.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">«ch» kan uttalast mjukt eller hardt. I nokre ord liknar han norsk «kj» (som i «kjøpe»), i andre er han ein hard lyd bak i munnen, nærare «k» (som i skotsk «loch»).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rekjnen) — rekne</div><div class=\"kurss-example\">zeichnen (tsaikjnen) — teikne</div><div class=\"kurss-example\">nicht (nikjt) — ikkje</div><div class=\"kurss-example\">schlecht (sjlekjt) — dårleg</div><div class=\"kurss-example\">mich (mikj) — meg</div><div class=\"kurss-example\">dich (dikj) — deg</div><div class=\"kurss-example\">Strauch (sjtraukh) — busk</div><div class=\"kurss-example\">noch (nåkh) — enno / framleis</div><div class=\"kurss-example\">Nacht (nakht) — natt</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">«sch» blir på tysk uttalt som norsk «sj» (som i «sjø»).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (sjūle) — skule</div><div class=\"kurss-example\">Schüler (sjȳler) — elev</div><div class=\"kurss-example\">Schiff (sjiff) — skip</div><div class=\"kurss-example\">Schraube (sjraube) — skrue</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp og st i byrjinga av ord</h4>\n              <p class=\"artikuli-explain\">I byrjinga av eit ord eller ei staving blir «sp» ofte uttalt som «sjp» og «st» som «sjt».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (sjpīlen) — spele / leike</div><div class=\"kurss-example\">Sprung (sjprung) — hopp</div><div class=\"kurss-example\">stehen (sjtēen) — stå</div><div class=\"kurss-example\">Stall (sjtall) — stall / fjøs</div><div class=\"kurss-example\">Stand (sjtant) — stand / stilling</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">«qu» blir på tysk vanlegvis uttalt som «kv».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvāl) — pine / kval</div><div class=\"kurss-example\">Quartier (kvartīr) — losji / kvarter</div><div class=\"kurss-example\">quer (kvēr) — på tvers</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s og z</h4>\n              <p class=\"artikuli-explain\">I byrjinga av eit ord høyrest «s» ofte ut som ein stemd s (som engelsk «z» i «zoo»; norsk har ikkje denne lyden). Bokstaven «z» blir på tysk uttalt som «ts».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zāgen) — seie</div><div class=\"kurss-example\">singen (zingen) — syngje</div><div class=\"kurss-example\">Rose (rå̄ze) — rose</div><div class=\"kurss-example\">Zahl (tsāl) — tal</div><div class=\"kurss-example\">Zeit (tsait) — tid</div><div class=\"kurss-example\">Zink (tsink) — sink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">På tysk blir «v» ofte uttalt som «f». I framandord høyrest han ofte ut som norsk «v».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (fāter) — far</div><div class=\"kurss-example\">von (fånn) — frå / av</div><div class=\"kurss-example\">viel (fīl) — mykje</div><div class=\"kurss-example\">vier (fīr) — fire</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Klavier (klavīr) — piano</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x og y</h4>\n              <p class=\"artikuli-explain\">«x» blir uttalt som «ks». «y» blir i nokre ord uttalt som «ü» (omtrent som norsk «y»).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (fēliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — øks</div><div class=\"kurss-example\">Mystik (mystik) — mystikk</div><div class=\"kurss-example\">Mythe (mȳte) — myte</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">«ß» blir på tysk uttalt som «s».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fūs) — fot</div><div class=\"kurss-example\">Füße (fȳse) — føter</div><div class=\"kurss-example\">Grüße (grȳse) — helsingar</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Samandrag</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sj</li><li>sp / st i byrjinga → sjp / sjt</li><li>qu → kv</li><li>z → ts</li><li>v ofte → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Grunnleggjande om verb</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Verb frå leksjon 1 og bøyinga deira.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Verb</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — å kome</div><div class=\"kurss-example\">gehen — å gå</div><div class=\"kurss-example\">stehen — å stå</div><div class=\"kurss-example\">singen — å syngje</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — eg kjem</div><div class=\"kurss-example\">du kommst — du kjem</div><div class=\"kurss-example\">er kommt — han kjem</div><div class=\"kurss-example\">sie kommt — ho kjem</div><div class=\"kurss-example\">wir kommen — vi kjem</div><div class=\"kurss-example\">ihr kommt — de kjem</div><div class=\"kurss-example\">sie kommen — dei kjem</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — eg går</div><div class=\"kurss-example\">du gehst — du går</div><div class=\"kurss-example\">er geht — han går</div><div class=\"kurss-example\">sie geht — ho går</div><div class=\"kurss-example\">wir gehen — vi går</div><div class=\"kurss-example\">ihr geht — de går</div><div class=\"kurss-example\">sie gehen — dei går</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — eg står</div><div class=\"kurss-example\">du stehst — du står</div><div class=\"kurss-example\">er steht — han står</div><div class=\"kurss-example\">sie steht — ho står</div><div class=\"kurss-example\">wir stehen — vi står</div><div class=\"kurss-example\">ihr steht — de står</div><div class=\"kurss-example\">sie stehen — dei står</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — eg syng</div><div class=\"kurss-example\">du singst — du syng</div><div class=\"kurss-example\">er singt — han syng</div><div class=\"kurss-example\">sie singt — ho syng</div><div class=\"kurss-example\">wir singen — vi syng</div><div class=\"kurss-example\">ihr singt — de syng</div><div class=\"kurss-example\">sie singen — dei syng</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Verb frå leksjon 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — å spele</div><div class=\"kurss-example\">arbeiten — å arbeide</div><div class=\"kurss-example\">fragen — å spørje</div><div class=\"kurss-example\">antworten — å svare</div><div class=\"kurss-example\">rechnen — å rekne</div><div class=\"kurss-example\">zeichnen — å teikne</div><div class=\"kurss-example\">tun — å gjere</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — eg spelar</div><div class=\"kurss-example\">du spielst — du spelar</div><div class=\"kurss-example\">er spielt — han spelar</div><div class=\"kurss-example\">sie spielt — ho spelar</div><div class=\"kurss-example\">wir spielen — vi spelar</div><div class=\"kurss-example\">ihr spielt — de spelar</div><div class=\"kurss-example\">sie spielen — dei spelar</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — eg arbeider</div><div class=\"kurss-example\">du arbeitest — du arbeider</div><div class=\"kurss-example\">er arbeitet — han arbeider</div><div class=\"kurss-example\">sie arbeitet — ho arbeider</div><div class=\"kurss-example\">wir arbeiten — vi arbeider</div><div class=\"kurss-example\">ihr arbeitet — de arbeider</div><div class=\"kurss-example\">sie arbeiten — dei arbeider</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — eg spør</div><div class=\"kurss-example\">du fragst — du spør</div><div class=\"kurss-example\">er fragt — han spør</div><div class=\"kurss-example\">sie fragt — ho spør</div><div class=\"kurss-example\">wir fragen — vi spør</div><div class=\"kurss-example\">ihr fragt — de spør</div><div class=\"kurss-example\">sie fragen — dei spør</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — eg svarar</div><div class=\"kurss-example\">du antwortest — du svarar</div><div class=\"kurss-example\">er antwortet — han svarar</div><div class=\"kurss-example\">sie antwortet — ho svarar</div><div class=\"kurss-example\">wir antworten — vi svarar</div><div class=\"kurss-example\">ihr antwortet — de svarar</div><div class=\"kurss-example\">sie antworten — dei svarar</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — eg reknar</div><div class=\"kurss-example\">du rechnest — du reknar</div><div class=\"kurss-example\">er rechnet — han reknar</div><div class=\"kurss-example\">sie rechnet — ho reknar</div><div class=\"kurss-example\">wir rechnen — vi reknar</div><div class=\"kurss-example\">ihr rechnet — de reknar</div><div class=\"kurss-example\">sie rechnen — dei reknar</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — eg teiknar</div><div class=\"kurss-example\">du zeichnest — du teiknar</div><div class=\"kurss-example\">er zeichnet — han teiknar</div><div class=\"kurss-example\">sie zeichnet — ho teiknar</div><div class=\"kurss-example\">wir zeichnen — vi teiknar</div><div class=\"kurss-example\">ihr zeichnet — de teiknar</div><div class=\"kurss-example\">sie zeichnen — dei teiknar</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — eg gjer</div><div class=\"kurss-example\">du tust — du gjer</div><div class=\"kurss-example\">er tut — han gjer</div><div class=\"kurss-example\">sie tut — ho gjer</div><div class=\"kurss-example\">wir tun — vi gjer</div><div class=\"kurss-example\">ihr tut — de gjer</div><div class=\"kurss-example\">sie tun — dei gjer</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Setningsoppbygging</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>I ein spørjesetning står verbet på tysk vanlegvis på første plass.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Døme</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Du kjem.</div><div class=\"kurss-example\">Kommst du? — Kjem du?</div><div class=\"kurss-example\">Er singt. — Han syng.</div><div class=\"kurss-example\">Singt er? — Syng han?</div><div class=\"kurss-example\">Stehst du? — Står du?</div><div class=\"kurss-example\">Ja, ich stehe. — Ja, eg står.</div><div class=\"kurss-example\">Geht ihr? — Går de?</div><div class=\"kurss-example\">Ja, wir gehen. — Ja, vi går.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Spørsmål med «was»</h4>\n              <p class=\"artikuli-explain\">Når eit spørsmål byrjar med eit spørjeord, står verbet på tysk vanlegvis rett etter spørjeordet.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Kva gjer du?</div><div class=\"kurss-example\">Was tut er? — Kva gjer han?</div><div class=\"kurss-example\">Was tut sie? — Kva gjer ho?</div><div class=\"kurss-example\">Was tun sie? — Kva gjer dei?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Nekting med «nicht»</h4>\n              <p class=\"artikuli-explain\">Når nektinga «nicht» gjeld verbet, står ho på tysk vanlegvis etter verbet.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Eg spelar ikkje.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul spør ikkje.</div><div class=\"kurss-example\">Er kommt nicht. — Han kjem ikkje.</div><div class=\"kurss-example\">Sie singen nicht. — Dei syng ikkje.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Setningar frå leksjon 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Spelar du?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nei, eg spelar ikkje, eg arbeider.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul spør ikkje, han arbeider.</div><div class=\"kurss-example\">Arbeitest du? — Arbeider du?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nei, eg arbeider ikkje, eg syng.</div><div class=\"kurss-example\">Was tut Paul? — Kva gjer Paul?</div><div class=\"kurss-example\">Er spielt. — Han spelar.</div><div class=\"kurss-example\">Was tut Marie? — Kva gjer Marie?</div><div class=\"kurss-example\">Sie singt. — Ho syng.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul spelar, men Marie syng.</div><div class=\"kurss-example\">Singt ihr? — Syng de?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nei, vi syng ikkje, vi arbeider.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Kva gjer Paul og Marie?</div><div class=\"kurss-example\">Sie fragen. — Dei spør.</div><div class=\"kurss-example\">Sie antworten nicht. — Dei svarar ikkje.</div><div class=\"kurss-example\">Wer arbeitet? — Kven arbeider?</div><div class=\"kurss-example\">Wir arbeiten. — Vi arbeider.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Vi reknar og teiknar.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Dei kjem, spør, svarar, arbeider, spelar, syng og går.</div></div>\n            </section>",
  "kurssLesson1": "            <h3>Leksjon 1</h3>\n            <p class=\"kurss-lesson-intro\">Første leksjon: verb i presens, glosar, uttale, grammatikk og omsetjing.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verb i presens</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verb og bøyinga deira i presens.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — kome</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>eg kjem</span><span>du</span><strong>kommst</strong><span>du kjem</span><span>er / sie</span><strong>kommt</strong><span>han / ho kjem</span><span>wir</span><strong>kommen</strong><span>vi kjem</span><span>ihr</span><strong>kommt</strong><span>de kjem</span><span>sie / Sie</span><strong>kommen</strong><span>dei / De kjem</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — gå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>eg går</span><span>du</span><strong>gehst</strong><span>du går</span><span>er / sie</span><strong>geht</strong><span>han / ho går</span><span>wir</span><strong>gehen</strong><span>vi går</span><span>ihr</span><strong>geht</strong><span>de går</span><span>sie / Sie</span><strong>gehen</strong><span>dei / De går</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>eg står</span><span>du</span><strong>stehst</strong><span>du står</span><span>er / sie</span><strong>steht</strong><span>han / ho står</span><span>wir</span><strong>stehen</strong><span>vi står</span><span>ihr</span><strong>steht</strong><span>de står</span><span>sie / Sie</span><strong>stehen</strong><span>dei / De står</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — syngje</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>eg syng</span><span>du</span><strong>singst</strong><span>du syng</span><span>er / sie</span><strong>singt</strong><span>han / ho syng</span><span>wir</span><strong>singen</strong><span>vi syng</span><span>ihr</span><strong>singt</strong><span>de syng</span><span>sie / Sie</span><strong>singen</strong><span>dei / De syng</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Døme</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Glosar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Den omtrentlege uttalen av orda står i parentes, skriven med norske bokstavar.<br>Dette gjeld også i dei neste leksjonane.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — vi</div><div class=\"kurss-example\">I ordet «wir» blir i uttala lang.</div><div class=\"kurss-example\">kommen (kommen) — kome</div><div class=\"kurss-example\">gehen (gee-en) — gå</div><div class=\"kurss-example\">stehen (sjtee-en) — stå</div><div class=\"kurss-example\">singen (zingen) — syngje</div><div class=\"kurss-example\">du (doo) kommst — du kjem</div><div class=\"kurss-example\">er (eer) kommt — han kjem</div><div class=\"kurss-example\">sie (zii) kommt — ho kjem</div><div class=\"kurss-example\">wer (veer) — kven?</div><div class=\"kurss-example\">ja (ja) — ja</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Rett uttale, skriven med norske bokstavar, står i leksjonane.</div><div class=\"kurss-example\">Wir (viir) — vi. I ordet wir blir i alltid uttala lang.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiv</h4><div class=\"lesson1-grammar-note\">Grunnforma av verbet. Vanlegvis endar infinitiven på -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Presensendingar</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Ta bort <span class=\"lesson1-ending-accent\">-en</span> frå grunnforma av verbet og legg til endinga.</strong></p><p>Døme: kommen → komm + ending</p><div class=\"lesson1-ending-process\" aria-label=\"Slik blir presensendingane laga\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>grunnform</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>ta bort <span class=\"lesson1-ending-accent\">-en</span></strong><span>stammen blir att</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>stamme</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>legg til endinga</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Døme</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Spørjesetningar</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>I ei tysk spørjesetning flyttar verbet seg vanlegvis til første plass.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På norsk:<br>Du kjem.<br>Kjem du?</div><div class=\"kurss-example\">På tysk:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — du kjem<br>kommst du? — kjem du?</div><div class=\"kurss-example\">er singt — han syng<br>singt er? — syng han?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Skilnad i person</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — han kjem</div><div class=\"kurss-example\">sie kommt — ho kjem</div><div class=\"kurss-example\">sie kommen — dei kjem</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Omset</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 1 treningskort\">\n                    <span class=\"lesson1-training-progress\">Leksjon 1 · Omset: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kjem du?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikk på kortet for å sjå den tyske omsetjinga. Etter svaret viser neste klikk det neste kortet.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson2": "            <h3>Leksjon 2</h3>\n            <p class=\"kurss-lesson-intro\">Andre leksjon: dialogar, ord, uttale, grammatikk og omsetjing.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogar / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — leike; spele</div>\n                  <div class=\"kurss-example\">nein — nei</div>\n                  <div class=\"kurss-example\">nicht — ikkje</div>\n                  <div class=\"kurss-example\">arbeiten — arbeide</div>\n                  <div class=\"kurss-example\">fragen — spørje</div>\n                  <div class=\"kurss-example\">was tut er? — kva gjer han?</div>\n                  <div class=\"kurss-example\">was tun sie? — kva gjer dei?</div>\n                  <div class=\"kurss-example\">aber — men</div>\n                  <div class=\"kurss-example\">antworten — svare</div>\n                  <div class=\"kurss-example\">rechnen — rekne</div>\n                  <div class=\"kurss-example\">zeichnen — teikne</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I orda ich, nicht, rechnen, zeichnen blir lyden ch uttala mjukt, omtrent som kj-lyden i norske ord som kino og kjenne.</div><div class=\"kurss-example\">I orda arbeiten, zeichnen blir diftongen ei uttala omtrent som ai i det norske ordet hai.</div><div class=\"kurss-example\">Konsonantsambandet sp blir uttala som sjp: spielen (sjpiilen).</div><div class=\"kurss-example\">I verbet tun blir u uttala lang i alle personar.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Endingar med e</h4>\n                  <div class=\"lesson1-grammar-note\">Når verbstammen endar på t, d, chn, står det ein e framfor endingane -st og -t i bøyinga.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Spørjeord</h4>\n                  <div class=\"lesson1-grammar-note\">I spørjesetningar som byrjar med eit spørjeord, til dømes: kva? kven? kva for ein? kvifor? korfor? osb., står verbet rett etter spørjeordet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Kva gjer du?</div><div class=\"kurss-example\">Was tut er? — Kva gjer han?</div><div class=\"kurss-example\">Was tut sie? — Kva gjer ho?</div><div class=\"kurss-example\">Was tun sie? — Kva gjer dei?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Nekting med nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Når nektinga nicht gjeld verbet, står nektingsordet etter verbet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Han kjem ikkje.</div><div class=\"kurss-example\">Sie singen nicht. — Dei syng ikkje.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Omset</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 2 omsetjingskort\">\n                    <span class=\"lesson1-training-progress\">Leksjon 2 · Omset: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kven spør?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikk på kortet for å sjå den tyske omsetjinga. Etter svaret viser neste klikk det neste kortet.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson3": "            <h3>Leksjon 3</h3>\n            <p class=\"kurss-lesson-intro\">Tredje leksjon: dialogar, ord, uttale, grammatikk og omsetjing.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogar / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kven</div><div class=\"kurss-example\">was — kva</div><div class=\"kurss-example\">hier — her</div><div class=\"kurss-example\">dort — der</div><div class=\"kurss-example\">der Tisch — bordet</div><div class=\"kurss-example\">ein Tisch — eit bord</div><div class=\"kurss-example\">die Bank — benken</div><div class=\"kurss-example\">eine Bank — ein benk</div><div class=\"kurss-example\">liegen — liggje</div><div class=\"kurss-example\">liegt hier ein Buch? — ligg det ei bok her?</div><div class=\"kurss-example\">das Buch — boka</div><div class=\"kurss-example\">ein Buch — ei bok</div><div class=\"kurss-example\">hängen — henge</div><div class=\"kurss-example\">das Bild — biletet</div><div class=\"kurss-example\">ein Bild — eit bilete</div><div class=\"kurss-example\">die Tafel — tavla</div><div class=\"kurss-example\">eine Tafel — ei tavle</div><div class=\"kurss-example\">wie — korleis</div><div class=\"kurss-example\">ist — er</div><div class=\"kurss-example\">dick — tjukk</div><div class=\"kurss-example\">das Heft — skriveboka</div><div class=\"kurss-example\">ein Heft — ei skrivebok</div><div class=\"kurss-example\">dünn — tynn</div><div class=\"kurss-example\">niedrig — låg</div><div class=\"kurss-example\">hoch — høg</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Den lange i-lyden blir skriven ie på tysk: liegen (liigen), hier (hiir), wie (vii).</div><div class=\"kurss-example\">ck er ein dobbel k: dick (dikk).</div><div class=\"kurss-example\">I adjektiv og adverb blir endinga -ig uttala som ein lett -ich: niedrig (niidrikj).</div><div class=\"kurss-example\">Når endinga -ig får ein e etter seg: -ige, blir g uttala som ein vanleg g: niedrige (niidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Subjekt</h4><div class=\"lesson1-grammar-note\">På tysk svarar subjektet på spørsmålet wer? / was? og står i nominativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Med wer? spør ein etter personar.</div><div class=\"kurss-example\">Med was? spør ein etter ting.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artiklar</h4><div class=\"lesson1-grammar-note\">På tysk har substantiva 3 kjønn: hankjønn, hokjønn og inkjekjønn. Framfor substantivet står det vanlegvis eit lite ord som blir kalla artikkel. Dette ordet kan ikkje alltid omsetjast direkte.</div><h5 class=\"lesson2-subtitle\">Bunden artikkel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hankjønn — der</div><div class=\"kurss-example\">hokjønn — die</div><div class=\"kurss-example\">inkjekjønn — das</div><div class=\"kurss-example\">I fleirtal er den bundne artikkelen die for alle tre kjønna.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Ubunden artikkel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hankjønn — ein</div><div class=\"kurss-example\">hokjønn — eine</div><div class=\"kurss-example\">inkjekjønn — ein</div><div class=\"kurss-example\">Den ubundne artikkelen har ikkje fleirtal.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Eigennamn</h4><div class=\"lesson1-grammar-note\">Framfor eigennamn brukar ein ikkje artikkel.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Plassen til verbet</h4><div class=\"lesson1-grammar-note\">I ei forteljande setning står verbet på andre plass.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På tysk seier ein om ting som står loddrett, at tingen står:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Om ting som ligg vassrett, seier ein at dei ligg:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Ting kan også henge:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Omset</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 3 omsetjingskort\"><span class=\"lesson1-training-progress\">Leksjon 3 · Omset: 1 / 22</span><span class=\"lesson1-training-text\">Reknar du?</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å sjå den tyske omsetjinga. Etter svaret viser neste klikk det neste kortet.</p></div></div></details>",
  "kurssLesson4": "            <h3>Leksjon 4</h3>\n            <p class=\"kurss-lesson-intro\">Akkusativ, nehmen, hinlegen, hinausgehen og adjektiv.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogar / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — ta</div><div class=\"kurss-example\">er nimmt (nimt) — han tek</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — pennehaldaren</div><div class=\"kurss-example\">einen Federhalter — ein pennehaldar</div><div class=\"kurss-example\">zeigen — vise</div><div class=\"kurss-example\">schwarz (sjvarts) — svart</div><div class=\"kurss-example\">weiß (vais) — kvit</div><div class=\"kurss-example\">die Feder (dii feeder) — pennen</div><div class=\"kurss-example\">eine Feder — ein penn</div><div class=\"kurss-example\">spitz (sjpits) — spiss</div><div class=\"kurss-example\">hinlegen — leggje frå seg</div><div class=\"kurss-example\">legt hin — legg frå seg</div><div class=\"kurss-example\">das Mädchen (mætkjen) — jenta</div><div class=\"kurss-example\">das Messer — kniven</div><div class=\"kurss-example\">ein Messer — ein kniv</div><div class=\"kurss-example\">scharf — skarp</div><div class=\"kurss-example\">stumpf (sjtompf) — sløv</div><div class=\"kurss-example\">dann — så, deretter</div><div class=\"kurss-example\">hinaus — ut</div><div class=\"kurss-example\">hinausgehen — gå ut</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Endingane -en, -er, -el er trykklette, difor høyrest e i desse endingane berre svakt: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h kan på tysk vere både ein lyd og eit lengdeteikn for vokalen framfor.</div><div class=\"kurss-example\">Når h er lengdeteikn, blir h ikkje uttala som lyd: nehmen (neemen).</div><div class=\"kurss-example\">Når det berre kjem éin konsonant etter vokalen, blir vokalen uttala lang: die (dii) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akkusativ</h4><div class=\"lesson1-grammar-note\">I hokjønn og inkjekjønn er akkusativ lik nominativ. Berre hankjønn endrar seg.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronomen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — hankjønn</div><div class=\"kurss-example\">sie — hokjønn</div><div class=\"kurss-example\">es — inkjekjønn</div><div class=\"kurss-example\">fleirtal — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Delbare verb</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjektiv</h4><div class=\"lesson1-grammar-note\">Når adjektivet er predikativ i setninga, endrar det seg verken etter kjønn eller tal.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Nekting med nicht</h4><div class=\"lesson1-grammar-note\">Når nicht nektar eit adjektiv, står det framfor ordet som blir nekta.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Substantiv med endinga -chen og -lein er inkjekjønn: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Omset</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 4 omsetjingskort\"><span class=\"lesson1-training-progress\">Leksjon 4 · Omset: 1 / 16</span><span class=\"lesson1-training-text\">Jenta tek ein pennehaldar.</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å sjå den tyske omsetjinga. Etter svaret viser neste klikk det neste kortet.</p></div></div></details>",
  "kurssLesson5": "\n    <h3>Leksjon 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akkusativ, sitzen, fragen og endinga -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogar / setningar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zitsen) — sitje</div>\n        <div class=\"kurss-example\">fragen (fragen) — spørje</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — læraren</div>\n        <div class=\"kurss-example\">gut (goot) — godt, bra</div>\n        <div class=\"kurss-example\">wen (veen) — kven</div>\n        <div class=\"kurss-example\">loben — rose</div>\n        <div class=\"kurss-example\">der Schüler (sjyyler) — eleven</div>\n        <div class=\"kurss-example\">klein — liten</div>\n        <div class=\"kurss-example\">groß (grås) — stor</div>\n        <div class=\"kurss-example\">die Lehrerin — lærarinna</div>\n        <div class=\"kurss-example\">die Schülerin — skulejenta</div>\n        <div class=\"kurss-example\">schlecht (sjlekjt) — dårleg</div>\n        <div class=\"kurss-example\">tadeln — klandre, skjenne på</div>\n        <div class=\"kurss-example\">oder (åder) — eller</div>\n        <div class=\"kurss-example\">das Kind (kint) — barnet</div>\n        <div class=\"kurss-example\">artig (artikj) — snill</div>\n        <div class=\"kurss-example\">die Mutter — mora</div>\n        <div class=\"kurss-example\">lieben (liiben) — elske</div>\n        <div class=\"kurss-example\">der Vater (fater) — faren</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz er ein dobla z og blir uttala som ts: sitzen (zitsen).</div>\n        <div class=\"kurss-example\">v blir i tyske ord uttala som f: der Vater (fater).</div>\n        <div class=\"kurss-example\">ß blir kalla eszett og blir uttala som norsk s: groß (grås), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativ og akkusativ</h4><div class=\"lesson1-grammar-note\">På norsk svarar både subjektet og det direkte objektet på spørsmålet kven? eller kva?; på tysk står subjektet i nominativ og det direkte objektet i akkusativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På tysk er spørjeordet i nominativ wer? for personar og was? for ting.</div><div class=\"kurss-example\">I akkusativ er spørjeordet wen? for personar og was? for ting.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artikkelendring i akkusativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akkusativ</h4><div class=\"lesson1-grammar-note\">Verbet fragen tek akkusativ på tysk.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Endinga -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mange hokjønnsord blir avleidde med endinga -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Plassen til verbet</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I ei forteljande setning står verbet på andre plass.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Omset</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 5 omsetjingskort\"><span class=\"lesson1-training-progress\">Leksjon 5 · Omset: 1 / 16</span><span class=\"lesson1-training-text\">Kven elskar faren?</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å sjå den tyske omsetjinga. Etter svaret viser neste klikk det neste kortet.</p></div></div>\n    </details>\n  ",
  "kurssLesson6": "\n    <h3>Leksjon 6</h3>\n    <p class=\"kurss-lesson-intro\">Tal, fleirtal, omlyd og fleirtalsformer av substantiv.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogar / setningar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — ligg, er</div><div class=\"kurss-example\">der Bleistift (blaisjtift) — blyanten</div><div class=\"kurss-example\">einige (ainige) — nokre</div><div class=\"kurss-example\">hinlegen — leggje frå seg</div><div class=\"kurss-example\">legt hin — legg frå seg</div><div class=\"kurss-example\">wieder (viider) — igjen</div><div class=\"kurss-example\">aufmachen — opne</div><div class=\"kurss-example\">er macht auf — han opnar</div><div class=\"kurss-example\">anspitzen (ansjpitsen) — spisse</div><div class=\"kurss-example\">er spitzt an — han spissar</div><div class=\"kurss-example\">sich setzen — setje seg</div><div class=\"kurss-example\">setzt sich — set seg</div><div class=\"kurss-example\">der Schlüssel (sjlyssel) — nykelen</div><div class=\"kurss-example\">das Fenster (fenster) — vindauget</div><div class=\"kurss-example\">die Tafel (dii tafel) — tavla</div><div class=\"kurss-example\">der Garten — hagen</div><div class=\"kurss-example\">der Löffel — skeia</div><div class=\"kurss-example\">zählen (tsælen) — telje</div><div class=\"kurss-example\">die Nadel — nåla</div><div class=\"kurss-example\">was ist das — kva er det?</div><div class=\"kurss-example\">der Hammer — hammaren</div><div class=\"kurss-example\">die Hämmer — hamrane</div><div class=\"kurss-example\">der Deckel (deer dekkel) — loket</div><div class=\"kurss-example\">der Teller — tallerken</div><div class=\"kurss-example\">der Wagen — vogna</div><div class=\"kurss-example\">der Schlitten — sleden, kjelken</div><div class=\"kurss-example\">das Ding — tingen</div><div class=\"kurss-example\">die Dinge — tinga</div><div class=\"kurss-example\">wie sind die Dinge? — korleis er tinga?</div><div class=\"kurss-example\">voll (fål) — full</div><div class=\"kurss-example\">leer (leer) — tom</div><div class=\"kurss-example\">schwer (sjveer) — tung, vanskeleg</div><div class=\"kurss-example\">leicht — lett</div><div class=\"kurss-example\">der Eimer — bøtta</div><div class=\"kurss-example\">wieviel (viifiil) — kor mange</div><div class=\"kurss-example\">wieviel Nadeln — kor mange nåler</div><div class=\"kurss-example\">hier (hiir) — her</div><div class=\"kurss-example\">dort — der</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä er omlyden av vokalen a og blir uttala som ein kort eller lang æ-lyd.</div><div class=\"kurss-example\">Døme: das Mädchen (mætkjen), die Bänke (dii benke), der Vater (deer fater), die Väter (dii fæter).</div><div class=\"kurss-example\">ü er omlyden av vokalen u og blir uttala som norsk y: run leppene godt og sei i.</div><div class=\"kurss-example\">Døme: fünf, der Schlüssel (sjlyssel).</div><div class=\"kurss-example\">ö blir uttala med runde lepper medan ein prøver å seie e, omtrent som norsk ø: der Löffel.</div><div class=\"kurss-example\">Ein dobla vokal viser at vokalen er lang: leer (leer).</div><div class=\"kurss-example\">Diftongen eu blir uttala som oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatikk og forklaringar</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Det trykksterke prefikset i eit samansett verb blir skilt frå verbet i presens og står sist i setninga.</div><div class=\"kurss-example\">Døme: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Talordet éin har alle tre kjønn når det står saman med eit substantiv: hankjønn ein, hokjønn eine, inkjekjønn ein.</div><div class=\"kurss-example\">Døme: ein Schüler — éin elev; eine Schülerin — éi skulejente; ein Kind — eitt barn.</div><div class=\"kurss-example\">Tal: eins, zwei, drei, vier (fiir), fünf, sechs (zeks), sieben (ziiben), acht, neun (noin), zehn (tseen).</div><div class=\"kurss-example\">Kopulaverbet har på tysk ei eintalsform og ei fleirtalsform: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Som norsk det i det er brukar tysk her éi form for alle kjønn og tal: das.</div><div class=\"kurss-example\">Døme: det er ein hammar — das ist ein Hammer; det er ei nål — das ist eine Nadel; det er hamrar — das sind Hämmer; det er nåler — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vogn og der Schlitten — slede blir på tysk, som på norsk, bruka både i eintal og fleirtal.</div><div class=\"kurss-example\">Substantiv i hankjønn og inkjekjønn med endinga -er, -el, -en får ofte inga ending i fleirtal.</div><div class=\"kurss-example\">Døme: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Substantiv i hokjønn med endinga -el, -er får -n i fleirtal.</div><div class=\"kurss-example\">Døme: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Unntak: die Mutter (mor) — die Mütter (mødrer); die Tochter (dotter) — die Töchter (døtrer).</div><div class=\"kurss-example\">Den ubundne artikkelen har ikkje fleirtal: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">I ei forteljande setning står det finitte verbet på andre plass: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Omset</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 6 omsetjingskort\"><span class=\"lesson1-training-progress\">Leksjon 6 · Omset: 1 / 21</span><span class=\"lesson1-training-text\">Paul tek ein blyant og teiknar.</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å sjå den tyske omsetjinga. Etter svaret viser neste klikk det neste kortet.</p></div></div>\n    </details>\n  ",
  "kurssLesson7": "            <h3>Leksjon 7</h3>\n            <p class=\"kurss-lesson-intro\">Sjuande leksjon: imperativ, høflegheitsform og fleirtal.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogar / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — syngje</div><div class=\"kurss-example\">singe — syng</div><div class=\"kurss-example\">singt — syng (til fleire)</div><div class=\"kurss-example\">singen Sie — syng (høfleg form)</div><div class=\"kurss-example\">das Lied (das liit) — songen</div><div class=\"kurss-example\">Sie — De</div><div class=\"kurss-example\">zählen — telje</div><div class=\"kurss-example\">das Fräulein (froilain) — frøkna</div><div class=\"kurss-example\">der Müller — møllaren</div><div class=\"kurss-example\">öffnen — opne</div><div class=\"kurss-example\">das Fenster (fenster) — vindauget</div><div class=\"kurss-example\">alle — alle</div><div class=\"kurss-example\">der Spiegel (sjpiigel) — spegelen</div><div class=\"kurss-example\">der Lappen — filla, kluten</div><div class=\"kurss-example\">der Spaten — spaden</div><div class=\"kurss-example\">der Besen — sopelimen</div><div class=\"kurss-example\">die Schaufel — skuffa</div><div class=\"kurss-example\">die Schüssel — bollen, fatet</div><div class=\"kurss-example\">das Zimmer — rommet</div><div class=\"kurss-example\">das Ufer (oofer) — bredda, stranda</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp i byrjinga av eit ord eller ei staving blir uttala som sjp: der Spiegel (deer sjpiigel).</div><div class=\"kurss-example\">sch blir uttala som norsk sj, som i sjø: die Schaufel (dii sjaufel), die Schüssel (dii sjyssel).</div><div class=\"kurss-example\">Diftongen äu blir uttala omtrent som oi i utropet oi: das Fräulein (das froilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Imperativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativ i 2. person eintal svarar til 2. person eintal av verbet utan personendinga -st, med endinga -e lagd til.</div><div class=\"kurss-example\">Døme: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Svært ofte fell endinga -e bort når imperativforma då blir einstava: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Imperativ i fleirtal</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativ i 2. person fleirtal er lik 2. person fleirtal i presens, men blir bruka utan pronomen.</div><div class=\"kurss-example\">Døme: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Høflegheitsform med Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Høflegheitsforma med «De» svarar til 3. person fleirtal. Pronomenet Sie blir skrive med stor bokstav og står etter verbet.</div><div class=\"kurss-example\">Døme: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I verbet öffnen blir det for å gjere uttalen lettare skote inn ein e mellom stamme og ending i 2. og 3. person eintal og i 2. person fleirtal: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Øving</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 7 øvingskort\"><span class=\"lesson1-training-progress\">Leksjon 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — spørje</span></button><p class=\"lesson1-training-hint\">Trykk på kortet for å sjå imperativformene.</p></div></div></details>"
};

